    /* #651: decompression budget. A hostile or corrupted share blob can
       expand ~1000x (a ~64 KB link inflating to hundreds of MB), hanging or
       OOM-ing the tab before validSharePayload ever runs — the structural
       caps only apply AFTER full inflation. Read the stream with a hard
       byte budget and abort past it. 16 MiB is ~100x the largest realistic
       share (the validator caps structure at 100 workouts x 100 exercises
       x 100 sets of slim positional rows). */
    const SHARE_MAX_INFLATED_BYTES=16*1024*1024;
    /* Decompresses deflate-compressed bytes, capped at SHARE_MAX_INFLATED_BYTES. */
